// Board rules. PROVIDED: do not edit this file in Week 10.
use crate::data::ShipSpec;
use rand::RngExt;
use rand::rngs::StdRng;

pub const SIZE: usize = 10;

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Cell {
    Water,
    Ship,
    Hit,
    Miss,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Shot {
    Miss,
    Hit,
    AlreadyShot,
}

// board[row][col]. Row 0 is the top row (shown as 1); column 0 is A.
pub type Board = [[Cell; SIZE]; SIZE];

pub fn new_board() -> Board {
    [[Cell::Water; SIZE]; SIZE]
}

// True if a ship of this length starting at (row, col) stays on the board
// and covers only water.
pub fn can_place(board: &Board, row: usize, col: usize, length: usize, horizontal: bool) -> bool {
    if row >= SIZE || col >= SIZE {
        return false;
    }
    if horizontal && col + length > SIZE {
        return false;
    }
    if !horizontal && row + length > SIZE {
        return false;
    }
    for i in 0..length {
        let (r, c) = if horizontal {
            (row, col + i)
        } else {
            (row + i, col)
        };
        if board[r][c] != Cell::Water {
            return false;
        }
    }
    true
}

// Mark the ship's cells. Call can_place first.
pub fn place(board: &mut Board, row: usize, col: usize, length: usize, horizontal: bool) {
    for i in 0..length {
        if horizontal {
            board[row][col + i] = Cell::Ship;
        } else {
            board[row + i][col] = Cell::Ship;
        }
    }
}

// Place every ship at a random legal position. False if one will not fit.
pub fn place_fleet(board: &mut Board, fleet: &[ShipSpec], rng: &mut StdRng) -> bool {
    for spec in fleet {
        let mut placed = false;
        for _ in 0..1000 {
            let row = rng.random_range(0..SIZE);
            let col = rng.random_range(0..SIZE);
            let horizontal = rng.random_bool(0.5);
            if can_place(board, row, col, spec.length, horizontal) {
                place(board, row, col, spec.length, horizontal);
                placed = true;
                break;
            }
        }
        if !placed {
            return false;
        }
    }
    true
}

// Fire at (row, col). Panics if the position is off the board.
pub fn fire(board: &mut Board, row: usize, col: usize) -> Shot {
    match board[row][col] {
        Cell::Water => {
            board[row][col] = Cell::Miss;
            Shot::Miss
        }
        Cell::Ship => {
            board[row][col] = Cell::Hit;
            Shot::Hit
        }
        Cell::Hit | Cell::Miss => Shot::AlreadyShot,
    }
}

pub fn count_cells(board: &Board, kind: Cell) -> usize {
    let mut total = 0;
    for row in 0..SIZE {
        for col in 0..SIZE {
            if board[row][col] == kind {
                total += 1;
            }
        }
    }
    total
}

pub fn all_sunk(board: &Board) -> bool {
    count_cells(board, Cell::Ship) == 0
}

// "B7" -> Some((6, 1)): letter is the column, number is the row (1-based).
pub fn parse_coord(text: &str) -> Option<(usize, usize)> {
    let text = text.trim();
    let first = text.chars().next()?;
    if !first.is_ascii_alphabetic() {
        return None;
    }
    let col = (first.to_ascii_uppercase() as usize) - ('A' as usize);
    let row_number: usize = text[1..].trim().parse().ok()?;
    if col >= SIZE || row_number < 1 || row_number > SIZE {
        return None;
    }
    Some((row_number - 1, col))
}

// One character per cell. Ships are hidden unless `reveal` is true.
pub fn render(board: &Board, reveal: bool) -> String {
    let mut out = String::from("    A B C D E F G H I J\n");
    for row in 0..SIZE {
        out.push_str(&format!("{:>2}  ", row + 1));
        for col in 0..SIZE {
            let symbol = match board[row][col] {
                Cell::Water => '.',
                Cell::Ship => {
                    if reveal {
                        'S'
                    } else {
                        '.'
                    }
                }
                Cell::Hit => 'X',
                Cell::Miss => 'o',
            };
            out.push(symbol);
            if col + 1 < SIZE {
                out.push(' ');
            }
        }
        out.push('\n');
    }
    out
}

// Higher is better. Fewer shots score more; 0 if every cell was fired at.
pub fn score_for(shots: u32) -> u32 {
    let most = (SIZE * SIZE) as u32;
    if shots >= most { 0 } else { most - shots }
}
